#!/usr/bin/env python3\n\"\"\"Configuration for Task Loop backend\"\"\"\n\nimport os\nfrom typing import List\nfrom pydantic_settings import BaseSettings\n\nclass Settings(BaseSettings):\n    \"\"\"Application settings from environment variables\"\"\"\n    \n    # Environment\n    ENV: str = os.getenv('PYTHON_ENV', 'development')\n    DEBUG: bool = ENV == 'development'\n    \n    # Server\n    HOST: str = os.getenv('HOST', '0.0.0.0')\n    PORT: int = int(os.getenv('PORT', '8003'))\n    API_URL: str = os.getenv('VITE_API_URL', 'http://localhost:8003')\n    \n    # CORS\n    CORS_ORIGINS: List[str] = [\n        'http://localhost:5173',\n        'http://localhost:80',\n        'http://localhost',\n        os.getenv('FRONTEND_URL', 'http://localhost:5173')\n    ]\n    CORS_ALLOW_CREDENTIALS: bool = True\n    CORS_ALLOW_METHODS: List[str] = ['*']\n    CORS_ALLOW_HEADERS: List[str] = ['*']\n    \n    # Ollama\n    OLLAMA_BASE_URL: str = os.getenv('OLLAMA_HOST', 'http://localhost:11434')\n    OLLAMA_MODEL: str = os.getenv('OLLAMA_MODEL', 'qwen3.5:0.8b')\n    OLLAMA_TIMEOUT: int = int(os.getenv('OLLAMA_TIMEOUT', '240'))\n    \n    # Logging\n    LOG_LEVEL: str = os.getenv('LOG_LEVEL', 'INFO')\n    LOG_DIR: str = os.getenv('LOG_DIR', './logs')\n    \n    # Database (future)\n    DATABASE_URL: str = os.getenv('DATABASE_URL', 'sqlite:///./taskloom.db')\n    \n    class Config:\n        env_file = '.env.production'\n        case_sensitive = True\n\nsettings = Settings()\n\n# Production CORS\nif 'onrender.com' in settings.API_URL:\n    settings.CORS_ORIGINS = [settings.API_URL, 'https://taskloom-frontend.onrender.com']\n\nif 'herokuapp.com' in settings.API_URL:\n    settings.CORS_ORIGINS = [settings.API_URL, 'https://taskloom-frontend.herokuapp.com']\n\nprint(f\"[CONFIG] Environment: {settings.ENV}\")\nprint(f\"[CONFIG] CORS Origins: {settings.CORS_ORIGINS}\")\nprint(f\"[CONFIG] Ollama: {settings.OLLAMA_BASE_URL}\")\n"}}

